public class Temperatura {
    private double grados;
    private String unidad;

    Temperatura(double grados, String unidad) {
        this.unidad = unidad;
        if (grados >= -273.15 && grados <= 1000) {
            this.grados = grados;
        } else {
            System.out.println("Temperature out of range. Using 0" + unidad);
            this.grados = 0;
        }
    }

    public double getGrados() { return grados; }

    public void setGrados(double grados) {
        if (grados >= -273.15 && grados <= 1000) {
            this.grados = grados;
        } else {
            System.out.println("Error: temperature out of range (-273.15 to 1000)");
        }
    }

    public double aCelsius() {
        if (unidad.equals("F")) { return (grados - 32) * 5.0 / 9.0; }
        return grados;
    }

    public double aFahrenheit() {
        if (unidad.equals("C")) { return grados * 9.0 / 5.0 + 32; }
        return grados;
    }

    void mostrar() {
        System.out.println(grados + "°" + unidad + " | Celsius: " + String.format("%.1f", aCelsius()) + "°C | Fahrenheit: " + String.format("%.1f", aFahrenheit()) + "°F");
    }

    public static void main(String[] args) {
        Temperatura t1 = new Temperatura(100, "C");
        Temperatura t2 = new Temperatura(212, "F");
        Temperatura t3 = new Temperatura(-300, "C");
        t1.mostrar();
        t2.mostrar();
        t3.mostrar();
        t1.setGrados(5000);
    }
}

