public class Producto {
    private String nombre;
    private double precio;
    private int stock;

    Producto(String nombre, double precio, int stock) {
        this.nombre = nombre;
        if (precio > 0) { this.precio = precio; } else { System.out.println("Invalid price, $1.00 used"); this.precio = 1.00; }
        if (stock >= 0) { this.stock = stock; } else { System.out.println("Invalid stock, 0 used"); this.stock = 0; }
    }

    public String getNombre() { return nombre; }
    public double getPrecio() { return precio; }
    public int getStock() { return stock; }

    public void setPrecio(double precio) {
        if (precio > 0) { this.precio = precio; } else { System.out.println("Error: price must be greater than 0"); }
    }

    public void setStock(int stock) {
        if (stock >= 0) { this.stock = stock; } else { System.out.println("Error: stock cannot be negative"); }
    }

    public boolean vender(int cantidad) {
        if (cantidad <= 0) { System.out.println("Invalid quantity"); return false; }
        if (cantidad > stock) { System.out.println("Insufficient stock. Available: " + stock); return false; }
        stock -= cantidad;
        System.out.println("Sale completed: " + cantidad + " x " + nombre);
        return true;
    }

    public void reabastecer(int cantidad) {
        if (cantidad > 0) { stock += cantidad; System.out.println("Restocked: " + cantidad + " units of " + nombre);
        } else { System.out.println("Invalid quantity to restock"); }
    }

    public double calcularValorTotal() { return precio * stock; }

    void mostrar() { System.out.println(nombre + " - $" + precio + " | Stock: " + stock + " | Total: $" + calcularValorTotal()); }

    public static void main(String[] args) {
        Producto p = new Producto("Laptop", 1200.00, 10);
        p.mostrar();
        p.vender(3);
        p.mostrar();
        p.vender(20);
        p.reabastecer(5);
        p.mostrar();
        p.setPrecio(-50);
        p.setStock(-10);
    }
}
